        n_d0_div_den_c   = {div_den66[65], div_den66[63:0]};
        n_d0_div_neg_c   = n_d0_div_num_c[127] ^ div_den66[65];
        if (div_den66[64]) begin end
        anum128          = abs128(n_d0_div_num_c);
        aden64           = n_d0_div_den_c[64] ? (64'd0 - n_d0_div_den_c[63:0]) : n_d0_div_den_c[63:0];
        den_zero         = (aden64 == 64'd0);
        n_d1_safe_den_c  = aden64 | {63'd0, den_zero};
        n_d1_pre_sat_c   = den_zero | (anum128[127:64] >= n_d1_safe_den_c);
        n_d1_init_rem_c  = n_d1_pre_sat_c ? 64'd0 : anum128[127:64];
        n_d1_init_quot_c = anum128[63:0];

        // Cone C (`C7`, `C8`, `C9`, `C10`)
        g1_dc128        = ($signed({{62{n_c3_g1dc_hi_q[65]}}, n_c3_g1dc_hi_q}) <<< 32) +
                          $signed({{62{n_c2_g1dc_lo_q[65]}}, n_c2_g1dc_lo_q});
        r2_dsq128       = ($signed({{62{n_c6_r2dsq_hi_c[65]}}, n_c6_r2dsq_hi_c}) <<< 32) +
                          $signed({{62{n_c5_r2dsq_lo_c[65]}}, n_c5_r2dsq_lo_c});
        push_q49        = (g1_dc128 <<< 1) + r2_dsq128;
        n_c7_g0_cand_c  = g0_q + push_q49;
        lyap_ok         = (~fast_path_q) & (abs128(n_c7_g0_cand_q) <= abs128(g0_q));
        delta_act       = lyap_ok ? n_c0_dc_q : 33'sd0;
        n_c8_xp_c       = $signed(x_clamped_q + delta_act[31:0]);
        n_c8_dt_res_c   = delta_act[32] ? (64'd0 - {{31{delta_act[32]}}, $unsigned(delta_act)})
                                        : {31'd0, $unsigned(delta_act)};
        n_c8_g0_post_c  = lyap_ok ? n_c7_g0_cand_q : g0_q;
        n_c8_g1_post_c  = g1_q + (lyap_ok ? n_c4_r2_dc_q : 64'sd0);
        j0_op_out       = sym_shr128_33(n_c8_g0_post_c);
        j1_op_out       = sym_shr64_16(n_c8_g1_post_c);
        j0_au_next      = n_c8_g0_post_c + b0_eff_q;
        j0_au_out       = clamp_sym64($signed(j0_au_next[96:33]), 64'sh1000_0000_0000_0000);
        j1_au_out       = clamp_sym64($signed({{16{n_c8_g1_post_c[63]}}, n_c8_g1_post_c[63:16]}), 64'sh0000_2000_0000_0000);
        n_c9_j0_next_c  = $unsigned(op_mask_q ? j0_op_out : j0_au_out);
        n_c9_j1_next_c  = $unsigned(op_mask_q ? j1_op_out : j1_au_out);
        n_c9_sub_next_c = op_mask_q ? 64'd0 : {n_c8_g1_post_c[15:0], 15'd0, j0_au_next[32:0]};
        raw_chart          = (n_c8_xp_c > b_enter_q) ? {8'd0, next_hi_q}
                           : ((n_c8_xp_c < b_exit_q) ? {8'd0, next_lo_q} : state_w_q[5][31:16]);
        n_c10_chart_next_c = raw_chart & cap_mask16_q;
        n_c10_mode_proj_c  = (mode_req_q & (~kan_lock_q)) | (state_w_q[5][15:0] & kan_lock_q);
        n_c10_conv_c       = (abs128(n_c8_g0_post_c) <= 128'h0000_0000_0000_0000_0000_0008_0000_0000);
        if (&{1'b0, j0_au_next[127:97]}) begin end
    end

    // =========================================================================
    // Sequential Pipeline & Tickless Manifold State Machine
    // =========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st_q         <= 4'd0;
            iter_q       <= 5'd0;
            done_q       <= 1'b0;
            state_w_q    <= 512'd0;
            b0_q         <= 32'sd0;
            b1_q         <= 32'sd0;
            b2_q         <= 32'sd0;
            b_exit_q     <= 32'sd0;
            b_enter_q    <= 32'sd0;
            dt_max_q     <= 32'sd1;
            u_gain_q     <= 32'sd0;
            u_in_q       <= 32'sd0;
            next_lo_q    <= 8'd0;
            next_hi_q    <= 8'd0;
            kan_lock_q   <= 16'd0;
            cap_mask16_q <= 16'hFFFF;
            mode_req_q   <= 16'd0;
            op_mask_q    <= 1'b0;
            fast_path_q  <= 1'b0;
            x_clamped_q  <= 32'sd0;
            b0_eff_q     <= 128'sd0;
            g0_q         <= 128'sd0;
            g1_q         <= 64'sd0;
            r2_q         <= 32'sd0;
            d_mag_q      <= 64'd0;
            div_neg_q    <= 1'b0;
            pre_sat_q    <= 1'b0;
            sr_rem_q     <= 64'd0;
            sr_acc_q     <= 64'd0;
            sr_aux_q     <= 128'd0;
            n_a1_b1_x_q      <= 64'sd0;
            n_a2_x_sq_q      <= 64'd0;
            n_a4_b0_eff_q    <= 128'sd0;
            n_b6_g1_sq_q     <= 128'sd0;
            n_b7_g0_r2_q     <= 128'sd0;
            n_c0_dc_q        <= 33'sd0;
            n_c1_dsq_q       <= 64'sd0;
            n_c2_g1dc_lo_q   <= 66'sd0;
            n_c3_g1dc_hi_q   <= 66'sd0;
            n_c4_r2_dc_q     <= 64'sd0;
            n_c7_g0_cand_q   <= 128'sd0;
        end else begin
            done_q <= 1'b0;
            case (st_q)
                4'd0: begin
                    if (wr_valid_i) begin
                        case (wr_kind_i)
                            2'd0: state_w_q[wr_idx_i] <= wr_data_i;
                            2'd1: begin
                                case (wr_idx_i)
                                    3'd0: b0_q <= clamp_sym64_to_32(wr_data_i);
                                    3'd1: b1_q <= clamp_sym64_to_32(wr_data_i);
                                    3'd2: b2_q <= clamp_sym64_to_32(wr_data_i);
                                    3'd3: begin
                                        logic signed [31:0] ex_c, en_c;
                                        ex_c      = clamp_sym32(wr_data_i[63:32]);
                                        en_c      = clamp_sym32(wr_data_i[31:0]);
                                        b_exit_q  <= ex_c;
                                        b_enter_q <= (en_c < ex_c) ? ex_c : en_c;
                                    end
                                    3'd4: begin
                                        logic signed [31:0] dt_c;
                                        dt_c     = clamp_sym32(wr_data_i[63:32]);
                                        dt_max_q <= (dt_c < 32'sd1) ? 32'sd1 : dt_c;
                                        u_gain_q <= clamp_sym32(wr_data_i[31:0]);
                                    end
                                    3'd5: begin
                                        next_lo_q  <= wr_data_i[31:24];
                                        next_hi_q  <= wr_data_i[23:16];
                                        kan_lock_q <= wr_data_i[15:0];
                                    end
                                    default: begin end
                                endcase
                            end
                            2'd2: begin
                                if (wr_idx_i == 3'd0) begin
                                    cap_mask16_q <= wr_data_i[15:0];
                                    mode_req_q   <= wr_data_i[31:16];
                                end else if (wr_idx_i == 3'd1) begin
                                    u_in_q      <= clamp_sym64_to_32(wr_data_i);
                                    x_clamped_q <= x_in_clamped_c;
                                    fast_path_q <= 1'b0;
                                    st_q        <= 4'd1;
                                end
                            end
                            default: begin end
                        endcase
                    end
                end
                4'd1: begin
                    n_a1_b1_x_q     <= n_a1_b1_x_c;
                    n_a2_x_sq_q     <= n_a2_x_sq_c;
                    n_a4_b0_eff_q   <= n_a4_b0_eff_c;
                    b0_eff_q <= n_a4_b0_eff_c;
                    st_q <= 4'd2;
                end
                4'd2: begin
                    op_mask_q <= n_a10_op_mask_c;
                    g0_q      <= n_a10_g0_c;
                    g1_q      <= n_a10_g1_c;
                    r2_q      <= n_a10_r2_c;
                    if (!n_a10_active_c) begin
                        fast_path_q <= 1'b1;
                        st_q        <= 4'd11;
                    end else if (!n_a10_has_r2_c) begin
                        d_mag_q <= 64'd0;
                        st_q    <= 4'd7;
                    end else begin
                        st_q <= 4'd3;
                    end
                end
                4'd3: begin
                    n_b6_g1_sq_q  <= n_b6_g1_sq_c;
                    st_q <= 4'd4;
                end
                4'd4: begin
                    n_b7_g0_r2_q  <= n_b7_g0_r2_c;
                    st_q <= 4'd5;
                end
                4'd5: begin
                    if (n_b8_disc_c[127]) begin
                        d_mag_q <= 64'h8000_0000_0000_0000;
                        st_q    <= 4'd7;
                    end else if (!n_b8_pos_nz_c) begin
                        d_mag_q <= 64'd0;
                        st_q    <= 4'd7;
                    end else begin
                        sr_rem_q <= 64'd0;
                        sr_acc_q <= 64'd0;
                        sr_aux_q <= $unsigned(n_b8_disc_c);
                        iter_q   <= 5'd31;
                        st_q     <= 4'd6;
                    end
                end
                4'd6: begin
                    sr_rem_q <= rad2_rem_w[2];
                    sr_acc_q <= rad2_acc_w[2];
                    sr_aux_q <= rad2_aux_w[2];
                    if (iter_q == 5'd0) begin
                        d_mag_q <= rad2_acc_w[2] + {63'd0, (rad2_rem_w[2] > rad2_acc_w[2])};
                        st_q    <= 4'd7;
                    end else begin
                        iter_q <= iter_q - 5'd1;
                    end
                end
                4'd7: begin
                    div_neg_q <= n_d0_div_neg_c;
                    pre_sat_q <= n_d1_pre_sat_c;
                    sr_rem_q  <= n_d1_init_rem_c;
                    sr_acc_q  <= n_d1_init_quot_c;
                    sr_aux_q  <= {64'd0, n_d1_safe_den_c};
                    if (n_d1_pre_sat_c) begin
                        st_q   <= 4'd9;
                    end else begin
                        iter_q <= 5'd31;
                        st_q   <= 4'd8;
                    end
                end
                4'd8: begin
                    sr_rem_q <= rad2_rem_w[2];
                    sr_acc_q <= rad2_acc_w[2];
                    if (iter_q == 5'd0) begin
                        st_q <= 4'd9;
                    end else begin
                        iter_q <= iter_q - 5'd1;
                    end
                end
                4'd9: begin
                    n_c0_dc_q       <= n_c0_dc_c;
                    n_c1_dsq_q      <= n_c1_dsq_c;
                    n_c2_g1dc_lo_q  <= n_c2_g1dc_lo_c;
                    n_c3_g1dc_hi_q  <= n_c3_g1dc_hi_c;
                    st_q <= 4'd10;
                end
                4'd10: begin
                    n_c4_r2_dc_q    <= n_c4_r2_dc_c;
                    n_c7_g0_cand_q  <= n_c7_g0_cand_c;
                    st_q <= 4'd11;
                end
                4'd11: begin
                    state_w_q[0] <= n_c9_j0_next_c;
                    state_w_q[1] <= n_c9_j1_next_c;
                    state_w_q[2] <= {{32{r2_q[31]}}, $unsigned(r2_q)};
                    state_w_q[3] <= {{32{n_c8_xp_c[31]}}, $unsigned(n_c8_xp_c)};
                    state_w_q[4] <= n_c8_dt_res_c;
                    state_w_q[5] <= {32'd0, n_c10_chart_next_c, n_c10_mode_proj_c};
                    state_w_q[6] <= {state_w_q[6][63:32] + 32'd1, 31'd0, n_c10_conv_c};
                    state_w_q[7] <= n_c9_sub_next_c;
                    fast_path_q  <= 1'b0;
                    done_q       <= 1'b1;
                    st_q         <= 4'd0;
                end
                default: begin
                    fast_path_q <= 1'b0;
                    st_q        <= 4'd0;
                end
            endcase
        end
    end

    assign ready_o   = (st_q == 4'd0);
    assign done_o    = done_q;
    assign rd_data_o = state_w_q[rd_idx_i];

`ifndef SYNTHESIS
    /* verilator lint_off UNUSEDPARAM */
    /* verilator lint_off UNUSEDSIGNAL */
    localparam int PROFILE_DSP_COUNT = 3;
    localparam int PROFILE_MAX_DEPTH = 36;
    localparam int CORE_DFF_BITS     = 1490;
    logic [4095:0] sim_dff_snap_w;
    assign sim_dff_snap_w = {
        2606'd0,
        st_q, iter_q, op_mask_q, fast_path_q, g0_q, g1_q, r2_q, d_mag_q,
        div_neg_q, pre_sat_q, sr_rem_q, sr_acc_q, sr_aux_q,
        n_a1_b1_x_q,
        n_a2_x_sq_q,
        n_a4_b0_eff_q,
        n_b6_g1_sq_q,
        n_b7_g0_r2_q,
        n_c0_dc_q,
        n_c1_dsq_q,
        n_c2_g1dc_lo_q,
        n_c3_g1dc_hi_q,
        n_c4_r2_dc_q,
        n_c7_g0_cand_q
    };
    /* verilator lint_on UNUSEDSIGNAL */
    /* verilator lint_on UNUSEDPARAM */
`endif

`ifdef FORMAL
    localparam int NUM_STATES = 12;
    logic               f_past_valid_q;
    logic               f_past_rst_n_q;
    logic               f_past_ready_q;
    logic [3:0]        f_past_st_q;
    logic [511:0]       f_past_state_w_q;
    logic signed [31:0] f_past_b0_q;
    logic signed [31:0] f_past_b1_q;
    logic signed [31:0] f_past_b2_q;
    logic signed [31:0] f_past_b_exit_q;
    logic signed [31:0] f_past_b_enter_q;
    logic signed [31:0] f_past_dt_max_q;
    logic signed [31:0] f_past_u_gain_q;
    logic signed [31:0] f_past_u_in_q;
    logic [7:0]         f_past_next_lo_q;
    logic [7:0]         f_past_next_hi_q;
    logic [15:0]        f_past_cap_q;
    logic [15:0]        f_past_mreq_q;
    logic [15:0]        f_past_mode_q;
    logic [15:0]        f_past_lock_q;
    initial f_past_valid_q = 1'b0;
    always @(posedge clk) begin
        f_past_valid_q   <= 1'b1;
        f_past_rst_n_q   <= rst_n;
        f_past_ready_q   <= ready_o;
        f_past_st_q      <= st_q;
        f_past_state_w_q <= state_w_q;
        f_past_b0_q      <= b0_q;
        f_past_b1_q      <= b1_q;
        f_past_b2_q      <= b2_q;
        f_past_b_exit_q  <= b_exit_q;
        f_past_b_enter_q <= b_enter_q;
        f_past_dt_max_q  <= dt_max_q;
        f_past_u_gain_q  <= u_gain_q;
        f_past_u_in_q    <= u_in_q;
        f_past_next_lo_q <= next_lo_q;
        f_past_next_hi_q <= next_hi_q;
        f_past_cap_q     <= cap_mask16_q;
        f_past_mreq_q    <= mode_req_q;
        f_past_mode_q    <= state_w_q[5][15:0];
        f_past_lock_q    <= kan_lock_q;
    end
    always_comb begin
        if (!rst_n) begin
            assert (st_q == 4'd0);
            assert (ready_o && !done_o && !fast_path_q);
            assert (dt_max_q == 32'sd1);
            assert (cap_mask16_q == 16'hFFFF);
        end
        if (ready_o) begin
            assert (dsp_en_c[0] == 1'b0);
            assert (dsp_en_c[1] == 1'b0);
            assert (dsp_en_c[2] == 1'b0);
            assert (rad2_en_c == 1'b0);
        end
        if (f_past_valid_q && f_past_rst_n_q && rst_n) begin
            if (!f_past_ready_q) begin
                assert (b0_q == f_past_b0_q);
                assert (b1_q == f_past_b1_q);
                assert (b2_q == f_past_b2_q);
                assert (b_exit_q == f_past_b_exit_q);
                assert (b_enter_q == f_past_b_enter_q);
                assert (dt_max_q == f_past_dt_max_q);
                assert (u_gain_q == f_past_u_gain_q);
                assert (u_in_q == f_past_u_in_q);
                assert (next_lo_q == f_past_next_lo_q);
                assert (next_hi_q == f_past_next_hi_q);
                assert (kan_lock_q == f_past_lock_q);
                assert (cap_mask16_q == f_past_cap_q);
                assert (mode_req_q == f_past_mreq_q);
                if (int'(f_past_st_q) != (NUM_STATES - 1)) begin
                    assert (!done_o);
                    assert (state_w_q == f_past_state_w_q);
                end
            end
            if (int'(f_past_st_q) >= NUM_STATES) begin
                assert (st_q == 4'd0);
                assert (ready_o && !done_o && !fast_path_q);
            end
            if (done_o) begin
                assert (ready_o);
                assert (int'(f_past_st_q) == (NUM_STATES - 1));
                assert ((state_w_q[5][15:0] & f_past_lock_q) == (f_past_mode_q & f_past_lock_q));
            end
        end
    end
`endif
endmodule

module ele_flow_atlas_top #(
    parameter int MAX_CHARTS = 16
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        cmd_valid_i,
    input  logic [2:0]  cmd_op_i,
    input  logic [2:0]  cmd_word_i,
    input  logic [15:0] cmd_aux_i,
    input  logic [63:0] cmd_data_i,
    output logic        ready_o,
    output logic        step_done_o,
    output logic        swap_done_o,
    output logic        swap_accepted_o,
    output logic [63:0] rd_data_o
);
    localparam int SLOT_W     = (MAX_CHARTS <= 2) ? 1 : $clog2(MAX_CHARTS);
    localparam int SRAM_DEPTH = MAX_CHARTS * 8;
    localparam int SRAM_AW    = $clog2(SRAM_DEPTH);
    localparam logic [15:0] HW_MASK16 = 16'(MAX_CHARTS - 1);

    // 64-bit Bus Command Opcodes
    localparam logic [2:0] CMD_NOP         = 3'd0;
    localparam logic [2:0] CMD_LOAD_STATE  = 3'd1;
    localparam logic [2:0] CMD_SET_CAP     = 3'd2;
    localparam logic [2:0] CMD_WRITE_CHART = 3'd3;
    localparam logic [2:0] CMD_STAGE_CAND  = 3'd4;
    localparam logic [2:0] CMD_STEP        = 3'd5;
    localparam logic [2:0] CMD_SWAP        = 3'd6;

    localparam logic [2:0] TOP_IDLE        = 3'd0;
    localparam logic [2:0] TOP_FETCH_BOUND = 3'd1;
    localparam logic [2:0] TOP_START_CORE  = 3'd2;
    localparam logic [2:0] TOP_WAIT_CORE   = 3'd3;
    localparam logic [2:0] TOP_SWAP_CHK    = 3'd4;
    localparam logic [2:0] TOP_SWAP_COMMIT = 3'd5;

    logic [2:0]            top_st_q;
    logic [2:0]            beat_q;
    logic [15:0]           cap_mask_q;
    logic [MAX_CHARTS-1:0] slot_valid_q;
    logic [SLOT_W-1:0]     act_slot_q;
    logic [15:0]           mode_hold_q;
    logic [63:0]           u_ext_hold_q;
    logic [5:0][63:0]      cand_buf_q;
    logic [SLOT_W-1:0]     swap_slot_q;
    logic [31:0]           swap_epoch_q;
    logic                  step_done_q;
    logic                  swap_done_q;
    logic                  swap_acc_q;

    logic                  sram_ce_c;
    logic                  sram_we_c;
    logic [SRAM_AW-1:0]    sram_addr_c;
    logic [63:0]           sram_wdata_c;
    logic [63:0]           sram_rdata_w;

    ele_sram_1rw64 #(
        .DEPTH  (SRAM_DEPTH),
        .ADDR_W (SRAM_AW)
    ) u_chart_sram (
        .clk     (clk),
        .ce_i    (sram_ce_c),
        .we_i    (sram_we_c),
        .addr_i  (sram_addr_c),
        .wdata_i (sram_wdata_c),
        .rdata_o (sram_rdata_w)
    );

    logic        core_wr_valid_c;
    logic [1:0]  core_wr_kind_c;
    logic [2:0]  core_wr_idx_c;
    logic [63:0] core_wr_data_c;
    logic        core_ready_w;
    logic        core_done_w;
    logic [2:0]  core_rd_idx_c;
    logic [63:0] core_rd_data_w;

    ele_flow_core u_core (
        .clk        (clk),
        .rst_n      (rst_n),
        .wr_valid_i (core_wr_valid_c),
        .wr_kind_i  (core_wr_kind_c),
        .wr_idx_i   (core_wr_idx_c),
        .wr_data_i  (core_wr_data_c),
        .ready_o    (core_ready_w),
        .done_o     (core_done_w),
        .rd_idx_i   (core_rd_idx_c),
        .rd_data_o  (core_rd_data_w)
    );

    logic [31:0] swap_cur_ep_c;
    logic        swap_fw_ok_c;
    always_comb begin
        swap_cur_ep_c = slot_valid_q[swap_slot_q] ? sram_rdata_w[63:32] : 32'd0;
        swap_fw_ok_c  = (swap_epoch_q > swap_cur_ep_c) &
                        ({8'd0, cand_buf_q[5][31:24]} <= cap_mask_q) &
                        ({8'd0, cand_buf_q[5][23:16]} <= cap_mask_q) &
                        ($signed(cand_buf_q[4][63:32]) > 32'sd0) &
                        ($signed(cand_buf_q[3][63:32]) <= $signed(cand_buf_q[3][31:0]));
    end

    logic [SLOT_W-1:0] step_slot_c;
    logic [SLOT_W-1:0] swap_req_slot_c;
    logic [SLOT_W-1:0] wr_chart_slot_c;
    wire               unused_aux_hi_ok = &{1'b0, cmd_aux_i[15:SLOT_W]};

    always_comb begin
        core_rd_idx_c   = (top_st_q == TOP_IDLE && cmd_valid_i && cmd_op_i == CMD_STEP) ? 3'd5 : cmd_word_i;
        step_slot_c     = core_rd_data_w[16 +: SLOT_W] & cap_mask_q[SLOT_W-1:0];
        swap_req_slot_c = cmd_aux_i[SLOT_W-1:0] & cap_mask_q[SLOT_W-1:0];
        wr_chart_slot_c = cmd_aux_i[SLOT_W-1:0];

        sram_ce_c       = 1'b0;
        sram_we_c       = 1'b0;
        sram_addr_c     = {SRAM_AW{1'b0}};
        sram_wdata_c    = 64'd0;

        core_wr_valid_c = 1'b0;
        core_wr_kind_c  = 2'd0;
        core_wr_idx_c   = 3'd0;
        core_wr_data_c  = 64'd0;

        case (top_st_q)
            TOP_IDLE: begin
                if (cmd_valid_i && core_ready_w) begin
                    case (cmd_op_i)
                        CMD_LOAD_STATE: begin
                            core_wr_valid_c = 1'b1;
                            core_wr_kind_c  = 2'd0;
                            core_wr_idx_c   = cmd_word_i;
                            core_wr_data_c  = cmd_data_i;
                        end
                        CMD_WRITE_CHART: begin
                            sram_ce_c    = 1'b1;
                            sram_we_c    = 1'b1;
                            sram_addr_c  = {wr_chart_slot_c, cmd_word_i};
                            sram_wdata_c = cmd_data_i;
                        end
                        CMD_STEP: begin
                            sram_ce_c       = 1'b1;
                            sram_we_c       = 1'b0;
                            sram_addr_c     = {step_slot_c, 3'd0};
                            core_wr_valid_c = 1'b1;
                            core_wr_kind_c  = 2'd2;
                            core_wr_idx_c   = 3'd0;
                            core_wr_data_c  = {32'd0, cmd_aux_i, cap_mask_q};
                        end
                        CMD_SWAP: begin
                            sram_ce_c   = 1'b1;
                            sram_we_c   = 1'b0;
                            sram_addr_c = {swap_req_slot_c, 3'd6};
                        end
                        default: begin end
                    endcase
                end
            end
            TOP_FETCH_BOUND: begin
                core_wr_valid_c = 1'b1;
                core_wr_kind_c  = 2'd1;
                core_wr_idx_c   = beat_q;
                core_wr_data_c  = slot_valid_q[act_slot_q] ? sram_rdata_w : 64'd0;
                if (beat_q < 3'd5) begin
                    sram_ce_c   = 1'b1;
                    sram_we_c   = 1'b0;
                    sram_addr_c = {act_slot_q, beat_q + 3'd1};
                end
            end
            TOP_START_CORE: begin
                core_wr_valid_c = 1'b1;
                core_wr_kind_c  = 2'd2;
                core_wr_idx_c   = 3'd1;
                core_wr_data_c  = u_ext_hold_q;
            end
            TOP_SWAP_CHK: begin
                if (swap_fw_ok_c) begin
                    sram_ce_c    = 1'b1;
                    sram_we_c    = 1'b1;
                    sram_addr_c  = {swap_slot_q, 3'd0};
                    sram_wdata_c = cand_buf_q[0];
                end
            end
            TOP_SWAP_COMMIT: begin
                sram_ce_c = 1'b1;
                sram_we_c = 1'b1;
                if (beat_q < 3'd6) begin
                    sram_addr_c  = {swap_slot_q, beat_q};
                    sram_wdata_c = cand_buf_q[beat_q];
                end else if (beat_q == 3'd6) begin
                    sram_addr_c  = {swap_slot_q, 3'd7};
                    sram_wdata_c = 64'd0;
                end else begin
                    sram_addr_c  = {swap_slot_q, 3'd6};
                    sram_wdata_c = {swap_epoch_q, 32'd0};
                end
            end
            default: begin end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            top_st_q     <= TOP_IDLE;
            beat_q       <= 3'd0;
            cap_mask_q   <= HW_MASK16;
            slot_valid_q <= {MAX_CHARTS{1'b0}};
            act_slot_q   <= {SLOT_W{1'b0}};
            mode_hold_q  <= 16'd0;
            u_ext_hold_q <= 64'd0;
            cand_buf_q   <= 384'd0;
            swap_slot_q  <= {SLOT_W{1'b0}};
            swap_epoch_q <= 32'd0;
            step_done_q  <= 1'b0;
            swap_done_q  <= 1'b0;
            swap_acc_q   <= 1'b0;
        end else begin
            step_done_q <= 1'b0;
            swap_done_q <= 1'b0;
            swap_acc_q  <= 1'b0;

            case (top_st_q)
                TOP_IDLE: begin
                    if (cmd_valid_i && core_ready_w) begin
                        case (cmd_op_i)
                            CMD_SET_CAP: begin
                                cap_mask_q <= cmd_data_i[15:0] & HW_MASK16;
                            end
                            CMD_STAGE_CAND: begin
                                if (cmd_word_i < 3'd6) begin
                                    cand_buf_q[cmd_word_i] <= cmd_data_i;
                                end
                            end
                            CMD_WRITE_CHART: begin
                                if (cmd_word_i == 3'd7) begin
                                    slot_valid_q[wr_chart_slot_c] <= 1'b1;
                                end
                            end
                            CMD_STEP: begin
                                act_slot_q   <= step_slot_c;
                                mode_hold_q  <= cmd_aux_i;
                                u_ext_hold_q <= cmd_data_i;
                                beat_q       <= 3'd0;
                                top_st_q     <= TOP_FETCH_BOUND;
                            end
                            CMD_SWAP: begin
                                swap_slot_q  <= swap_req_slot_c;
                                swap_epoch_q <= cmd_data_i[31:0];
                                top_st_q     <= TOP_SWAP_CHK;
                            end
                            default: begin end
                        endcase
                    end
                end
                TOP_FETCH_BOUND: begin
                    if (beat_q == 3'd5) begin
                        top_st_q <= TOP_START_CORE;
                    end else begin
                        beat_q <= beat_q + 3'd1;
                    end
                end
                TOP_START_CORE: begin
                    top_st_q <= TOP_WAIT_CORE;
                end
                TOP_WAIT_CORE: begin
                    if (core_done_w) begin
                        step_done_q <= 1'b1;
                        top_st_q    <= TOP_IDLE;
                    end
                end
                TOP_SWAP_CHK: begin
                    if (!swap_fw_ok_c) begin
                        swap_done_q <= 1'b1;
                        swap_acc_q  <= 1'b0;
                        top_st_q    <= TOP_IDLE;
                    end else begin
                        beat_q   <= 3'd1;
                        top_st_q <= TOP_SWAP_COMMIT;
                    end
                end
                TOP_SWAP_COMMIT: begin
                    if (beat_q == 3'd7) begin
                        slot_valid_q[swap_slot_q] <= 1'b1;
                        swap_done_q               <= 1'b1;
                        swap_acc_q                <= 1'b1;
                        top_st_q                  <= TOP_IDLE;
                    end else begin
                        beat_q <= beat_q + 3'd1;
                    end
                end
                default: top_st_q <= TOP_IDLE;
            endcase
        end
    end

    wire unused_mode_hold_ok = &{1'b0, mode_hold_q, CMD_NOP};
    assign ready_o         = (top_st_q == TOP_IDLE) & core_ready_w;
    assign step_done_o     = step_done_q;
    assign swap_done_o     = swap_done_q;
    assign swap_accepted_o = swap_acc_q;
    assign rd_data_o       = core_rd_data_w;

`ifdef FORMAL
    logic        f_past_valid_q;
    logic        f_past_rst_n_q;
    logic        f_past_ready_q;
    logic [2:0]  f_past_st_q;
    logic        f_past_fw_ok_q;
    logic [15:0] f_past_cap_q;
    logic [63:0] f_past_cand0_q;
    logic [63:0] f_past_cand5_q;
    initial f_past_valid_q = 1'b0;
    always @(posedge clk) begin
        f_past_valid_q <= 1'b1;
        f_past_rst_n_q <= rst_n;
        f_past_ready_q <= ready_o;
        f_past_st_q    <= top_st_q;
        f_past_fw_ok_q <= swap_fw_ok_c;
        f_past_cap_q   <= cap_mask_q;
        f_past_cand0_q <= cand_buf_q[0];
        f_past_cand5_q <= cand_buf_q[5];
    end
    always_comb begin
        if (!rst_n) begin
            assert (top_st_q == TOP_IDLE);
            assert (!step_done_o && !swap_done_o && !swap_accepted_o);
            assert (cap_mask_q == HW_MASK16);
            assert (slot_valid_q == {MAX_CHARTS{1'b0}});
        end
        assert ((cap_mask_q & (~HW_MASK16)) == 16'd0);
        if ((top_st_q == TOP_IDLE) && (!core_ready_w)) begin
            assert (!ready_o && !sram_ce_c && !sram_we_c && !core_wr_valid_c);
        end
        if ((top_st_q == TOP_FETCH_BOUND) || (top_st_q == TOP_START_CORE) || (top_st_q == TOP_WAIT_CORE)) begin
            assert (sram_we_c == 1'b0);
            assert (!ready_o);
        end
        if ((top_st_q == TOP_SWAP_CHK) && (!swap_fw_ok_c)) begin
            assert (sram_we_c == 1'b0);
        end
        if (f_past_valid_q && f_past_rst_n_q && rst_n) begin
            if (!f_past_ready_q) begin
                assert (cap_mask_q == f_past_cap_q);
                assert (cand_buf_q[0] == f_past_cand0_q);
                assert (cand_buf_q[5] == f_past_cand5_q);
            end
            if ((f_past_st_q == TOP_WAIT_CORE)) begin
                assert (!swap_done_o && !swap_accepted_o);
            end
            if ((f_past_st_q == TOP_SWAP_CHK) && (!f_past_fw_ok_q)) begin
                assert (swap_done_o && !swap_accepted_o);
            end
        end
    end
`endif
endmodule

/* verilator lint_on DECLFILENAME */
`default_nettype wire
